// Contrat de sortie de presti-dep-suivi@1 : le seul nœud final ; effets_faits reste vide en simulation.
const CONTRAT = 'presti-dep-suivi@1';
// ─── Gabarit « Contrat de sortie » 035-003 : au-dessus, CONTRAT seulement ; en dessous, le corps commun (empreinte tenue par le juge) ───
const STATUTS = ['ok', 'rien_a_faire', 'rejete', 'refuse', 'erreur'];
const liste = (x) => Array.isArray(x) ? x : [];
return $input.all().map((item) => {
  const j = item.json || {};
  const e = j.enveloppe && typeof j.enveloppe === 'object' ? j.enveloppe : {};
  const simulation = e.simulation !== false;
  const rejete = j.conforme === false;
  const statut = rejete ? 'rejete' : STATUTS.includes(j.statut) ? j.statut : 'erreur';
  const journal = liste(j.journal).slice(0, 200);
  if (rejete) journal.push({ evenement: 'contrat_rejete', agent: CONTRAT, objet_ref: null, decision: 'entrée hors contrat : aucun effet', simulation: simulation });
  return { json: {
    'contrat': CONTRAT,
    'statut': statut,
    'cle_idempotence': typeof e.cle_idempotence === 'string' ? e.cle_idempotence.slice(0, 80) : '',
    'simulation': simulation,
    'resultat': rejete || statut === 'erreur' ? null : (j.resultat && typeof j.resultat === 'object' ? j.resultat : null),
    'effets_prevus': rejete ? [] : liste(j.effets_prevus),
    'effets_faits': simulation || rejete ? [] : liste(j.effets_faits),
    'journal': journal,
    'erreurs': liste(j.erreurs).map(String).slice(0, 20),
  } };
});

// Suivi, étape 1 (A20) : AVANT tout geste, le contrôleur de conflit. Une offre sans la capacité « relances » (Essentiel, essai) n'a rien à contrôler : annulée, comme le cron. La PAUSE GÉNÉRALE (lib/agents/sortie.ts : seule la valeur exacte false ouvre la porte) est lue par le Cerveau et passée dans config.pause_generale : posée ou illisible (null), rien n'est contrôlé ni relancé, les relances restent dues. Les coordonnées des messages du client sont MASQUÉES avant de sortir du chef.
const ENVS = $("Contrat d'entrée").all().map((x) => x.json).filter((x) => x.conforme === true).map((x) => x.enveloppe);
const OBJ = []; const PAR_ID = {}; const AUTRES = [];
for (const e of ENVS) for (const ev of e.donnees.evenements) {
  if (ev.artisan_id !== e.organisation_id) { AUTRES.push({ id: ev.id, org: e.organisation_id }); continue; }
  if (ev.type !== 'relance_due' || PAR_ID[ev.id]) continue;
  PAR_ID[ev.id] = { e: e, ev: ev, o: ev.donnees }; OBJ.push(PAR_ID[ev.id]);
}
OBJ.sort((a, b) => (a.o.objet_type === b.o.objet_type ? 0 : a.o.objet_type === 'devis' ? -1 : 1));
const env = (e, contrat, cle, config, donnees) => ({ contrat: contrat, organisation_id: e.organisation_id, simulation: e.simulation, cle_idempotence: String(cle).slice(0, 80), trace: { execution_parent: String(e.trace.execution_parent), declencheur: 'presti-dep-suivi', tentative: e.trace.tentative }, config: config, donnees: donnees });
const sorties = (nom) => { const n = $(nom); return n.isExecuted ? n.all().map((x) => x.json) : []; };
const parCle = (nom, contrat) => { const m = {}; for (const s of sorties(nom)) if (s && s.contrat === contrat && typeof s.cle_idempotence === 'string') m[s.cle_idempotence] = s; return m; };
const bon = (s) => !!(s && s.statut === 'ok' && s.resultat);
const VIDE = [{ json: { vide: true } }];
const FMT_PARIS = new Intl.DateTimeFormat('en-US', { timeZone: 'Europe/Paris', weekday: 'short', year: 'numeric', month: '2-digit', day: '2-digit' });
const JOURS_ISO = { Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7 };
function paris(date) { const p = {}; for (const x of FMT_PARIS.formatToParts(date)) p[x.type] = x.value; return { jour: JOURS_ISO[p.weekday], date: p.year + '-' + p.month + '-' + p.day }; }
const jourDuLot = (e) => paris(new Date(Date.parse(e.donnees.maintenant))).jour === e.config.jour_du_lot;
const MAIL = /[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}/g;
const TEL = /(\+33|0033|\b0)\s?[1-9]([ .-]?\d{2}){4}\b/g;
const s = OBJ.filter(({ e }) => e.config.capacites.includes('relances') && e.config.pause_generale === false).map(({ e, ev, o }) => ({ json: env(e, 'lib-controler-conflit@1', 'rc:' + ev.id, { mots_escalade_artisan: e.config.mots_escalade_artisan },
  { objet_type: o.objet_type, objet_id: o.objet_id, dossier_id: o.dossier_id, statut: o.statut, main_prise: o.main_prise, exclu: o.exclu, carte: o.carte, ecartee_le: o.ecartee_le,
    historique: o.historique, stop: o.stop, messages_entrants: o.messages_entrants.map((t) => t.replace(MAIL, '[coordonnée]').replace(TEL, '[coordonnée]')), maintenant: e.donnees.maintenant }) }));
return s.length ? s : VIDE;

// Suivi, étape 2 : le palier atteint et non envoyé, le registre de 3 jours, le stop, les horaires (lib-relancer, 035-005). Seulement pour ce que le contrôleur laisse passer.
const ENVS = $("Contrat d'entrée").all().map((x) => x.json).filter((x) => x.conforme === true).map((x) => x.enveloppe);
const OBJ = []; const PAR_ID = {}; const AUTRES = [];
for (const e of ENVS) for (const ev of e.donnees.evenements) {
  if (ev.artisan_id !== e.organisation_id) { AUTRES.push({ id: ev.id, org: e.organisation_id }); continue; }
  if (ev.type !== 'relance_due' || PAR_ID[ev.id]) continue;
  PAR_ID[ev.id] = { e: e, ev: ev, o: ev.donnees }; OBJ.push(PAR_ID[ev.id]);
}
OBJ.sort((a, b) => (a.o.objet_type === b.o.objet_type ? 0 : a.o.objet_type === 'devis' ? -1 : 1));
const env = (e, contrat, cle, config, donnees) => ({ contrat: contrat, organisation_id: e.organisation_id, simulation: e.simulation, cle_idempotence: String(cle).slice(0, 80), trace: { execution_parent: String(e.trace.execution_parent), declencheur: 'presti-dep-suivi', tentative: e.trace.tentative }, config: config, donnees: donnees });
const sorties = (nom) => { const n = $(nom); return n.isExecuted ? n.all().map((x) => x.json) : []; };
const parCle = (nom, contrat) => { const m = {}; for (const s of sorties(nom)) if (s && s.contrat === contrat && typeof s.cle_idempotence === 'string') m[s.cle_idempotence] = s; return m; };
const bon = (s) => !!(s && s.statut === 'ok' && s.resultat);
const VIDE = [{ json: { vide: true } }];
const FMT_PARIS = new Intl.DateTimeFormat('en-US', { timeZone: 'Europe/Paris', weekday: 'short', year: 'numeric', month: '2-digit', day: '2-digit' });
const JOURS_ISO = { Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7 };
function paris(date) { const p = {}; for (const x of FMT_PARIS.formatToParts(date)) p[x.type] = x.value; return { jour: JOURS_ISO[p.weekday], date: p.year + '-' + p.month + '-' + p.day }; }
const jourDuLot = (e) => paris(new Date(Date.parse(e.donnees.maintenant))).jour === e.config.jour_du_lot;
const MAIL = /[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}/g;
const TEL = /(\+33|0033|\b0)\s?[1-9]([ .-]?\d{2}){4}\b/g;
const conf = parCle('Appeler lib-controler-conflit', 'lib-controler-conflit@1');
